//! Durable session lifecycle backed by embedded storage.
#![forbid(unsafe_code)]
use std::sync::Arc; use opencode_rk_contracts::{MessageId,MessageRecord,MessageRole,PayloadRef,SessionId,SessionState,SessionSummary,Timestamp}; use opencode_rk_storage::{Storage,StorageError}; use thiserror::Error;
#[derive(Clone)]pub struct SessionService{storage:Arc<Storage>} impl SessionService{#[must_use]pub fn new(storage:Arc<Storage>)->Self{Self{storage}}pub async fn create(&self,title:impl Into<String>)->Result<SessionSummary,SessionError>{let now=Timestamp::now();let session=SessionSummary{id:SessionId::new(),title:title.into(),state:SessionState::Active,created_at:now,updated_at:now,archived_at:None};let storage=Arc::clone(&self.storage);let candidate=session.clone();run_blocking(move||storage.create_session(&candidate)).await?;Ok(session)}pub async fn get(&self,id:SessionId)->Result<SessionSummary,SessionError>{let storage=Arc::clone(&self.storage);Ok(run_blocking(move||storage.get_session(id)).await?)}pub async fn list(&self,all:bool)->Result<Vec<SessionSummary>,SessionError>{let storage=Arc::clone(&self.storage);Ok(run_blocking(move||storage.list_sessions(all)).await?)}pub async fn rename(&self,id:SessionId,title:impl Into<String>)->Result<(),SessionError>{let storage=Arc::clone(&self.storage);let title=title.into();run_blocking(move||storage.rename_session(id,&title,Timestamp::now())).await?;Ok(())}pub async fn archive(&self,id:SessionId)->Result<(),SessionError>{let storage=Arc::clone(&self.storage);run_blocking(move||storage.archive_session(id,Timestamp::now())).await?;Ok(())}pub async fn append_text(&self,session_id:SessionId,role:MessageRole,text:impl Into<String>)->Result<MessageRecord,SessionError>{let body=PayloadRef::inline(text.into()).map_err(|e|SessionError::Contract(e.to_string()))?;let message=MessageRecord{id:MessageId::new(),session_id,role,body,created_at:Timestamp::now()};let storage=Arc::clone(&self.storage);let candidate=message.clone();run_blocking(move||storage.append_message(&candidate)).await?;Ok(message)}pub async fn append_blob(&self,session_id:SessionId,role:MessageRole,bytes:Vec<u8>)->Result<MessageRecord,SessionError>{let storage=Arc::clone(&self.storage);let(hash,byte_len)=run_blocking(move||storage.blob_store().put(&bytes).map(|i|(i.hash,i.raw_bytes))).await?;let message=MessageRecord{id:MessageId::new(),session_id,role,body:PayloadRef::blob(hash,byte_len),created_at:Timestamp::now()};let storage=Arc::clone(&self.storage);let candidate=message.clone();run_blocking(move||storage.append_message(&candidate)).await?;Ok(message)}pub async fn messages(&self,session_id:SessionId,limit:usize)->Result<Vec<MessageRecord>,SessionError>{let storage=Arc::clone(&self.storage);Ok(run_blocking(move||storage.list_messages(session_id,limit)).await?)}}
async fn run_blocking<T,F>(operation:F)->Result<T,SessionError>where T:Send+'static,F:FnOnce()->Result<T,StorageError>+Send+'static{tokio::task::spawn_blocking(operation).await.map_err(|e|SessionError::BlockingTask(e.to_string()))?.map_err(SessionError::Storage)}
#[derive(Debug,Error)]pub enum SessionError{#[error(transparent)]Storage(#[from]StorageError),#[error("blocking storage task failed: {0}")]BlockingTask(String),#[error("contract violation: {0}")]Contract(String)}
#[cfg(test)]mod tests{use super::*;use tempfile::tempdir;#[tokio::test]async fn lifecycle(){let temp=tempdir().unwrap();let storage=Arc::new(Storage::open_in_memory(temp.path().join("blobs")).unwrap());let first=SessionService::new(Arc::clone(&storage));let session=first.create("hello").await.unwrap();first.append_text(session.id,MessageRole::User,"message").await.unwrap();let recreated=SessionService::new(storage);assert_eq!(recreated.get(session.id).await.unwrap().title,"hello");assert_eq!(recreated.messages(session.id,50).await.unwrap().len(),1);}#[tokio::test]async fn archive_hides_default(){let temp=tempdir().unwrap();let storage=Arc::new(Storage::open_in_memory(temp.path().join("blobs")).unwrap());let service=SessionService::new(storage);let session=service.create("archive me").await.unwrap();service.archive(session.id).await.unwrap();assert!(service.list(false).await.unwrap().is_empty());assert_eq!(service.list(true).await.unwrap().len(),1);}#[tokio::test]async fn large_content_uses_blob(){let temp=tempdir().unwrap();let storage=Arc::new(Storage::open_in_memory(temp.path().join("blobs")).unwrap());let service=SessionService::new(storage);let session=service.create("blob").await.unwrap();let message=service.append_blob(session.id,MessageRole::Tool,vec![b'x';256*1024]).await.unwrap();assert!(matches!(message.body,PayloadRef::Blob{..}));}}
